<script setup lang="ts">import {ref,computed} from 'vue';import {failureAnalysis,failureSamples,failureSamplesPath,type FailureAnalysis,type FailureSample} from '../api/failures';import {downloadPath} from '../api/client';import {fixed,pct} from '../utils/format';import Notice from './common/Notice.vue';const props=defineProps<{resource:'runs'|'reports';ident:string;compact?:boolean}>();const {data,error,load}=failureAnalysis(()=>props.resource,()=>props.ident);const selected=ref('');const detail=ref<FailureSample[]|null>(null);const detailError=ref('');const busy=ref(false);const showAll=ref(false);const limit=computed(()=>showAll.value&&detail.value?detail.value.length:(props.compact?5:25));const display=computed(()=>detail.value?detail.value.slice(0,limit.value):[]);const selectedLabel=computed(()=>selected.value?data.value?.combinations.find(c=>c.key===selected.value)?.label||selected.value:'全部失败样本');const tolerance=computed(()=>data.value?String(data.value.comparison_tolerance):'—');async function inspect(key=''){busy.value=true;detailError.value='';showAll.value=false;try{detail.value=(await failureSamples(props.resource,props.ident,key)).samples;selected.value=key}catch(e){detailError.value=(e as Error).message}finally{busy.value=false}}async function download(key=''){busy.value=true;detailError.value='';try{await downloadPath(failureSamplesPath(props.resource,props.ident,key),'pulp-failed-samples.csv')}catch(e){detailError.value=(e as Error).message}finally{busy.value=false}}</script><template><section class="failure-panel"><div class="ledger-heading"><h2>失败原因与共同失守组合</h2><div class="actions heading-actions"><small v-if="data">{{data.failed}} / {{data.sample_count}} 个样本未通过</small><button v-if="data&&data.failed" class="secondary" :disabled="busy" @click="download('')">下载全部失败明细 ↓</button></div></div><Notice v-if="error" :message="error"/><Notice v-if="detailError" :message="detailError"/><div v-if="error" class="empty">历史结果缺少完整扰动样本或质量界限，无法补算失败组合。请核对上方说明后重新运行情景生成同批样本。</div><template v-else-if="data"><div class="failure-summary"><div><small>失败样本</small><strong>{{data.failed}}</strong><span>{{pct(data.failed_rate)}} 的样本至少一项超界</span></div><div><small>组合合计 / 失败样本</small><strong>{{data.reconciliation.combination_sample_total}} / {{data.reconciliation.failed_samples}}</strong><span>{{data.reconciliation.balanced?'逐条对账一致':'存在未归类或重复归类'}}</span></div><div><small>比较与来源</small><strong>±{{tolerance}}</strong><span>沿用原运行容差 · {{data.resampled?'重新抽样':'复用存档样本'}} · seed {{data.seed ?? '—'}}</span></div></div><h3>单项失败计数</h3><p class="method-note">同一失败样本可违反多项，下列计数彼此可重叠，不能相加当作失败样本数。上界超界按各自单位对照上下限与容差。</p><div class="table-wrap"><table><thead><tr><th>失败项</th><th>界限</th><th>超界样本</th><th>说明</th></tr></thead><tbody><tr v-for="c in data.single_failures" :key="c.code"><td>{{c.label}}</td><td>{{c.side==='low'?'≥':'≤'}} {{c.property==='recycled'?pct(c.bound):fixed(c.bound,2)}}</td><td>{{c.count}}</td><td><small>{{c.side==='low'?'低于下界减容差':'高于上界加容差'}}</small></td></tr></tbody></table></div><h3>互斥组合</h3><p class="method-note">每个失败样本只归入一个“实际违反的全部界限”组合，组合之间互斥；组合样本数合计 {{data.reconciliation.combination_sample_total}} 与失败样本 {{data.reconciliation.failed_samples}} 逐条对账。</p><div class="combination-list"><article v-for="group in data.combinations" :key="group.key" :class="{active:selected===group.key}"><div><span class="eyebrow">{{group.kind==='single'?'单项失守':'共同失守'}}</span><h4>{{group.label}}</h4><small>{{group.count}} 个样本 · 序号 {{group.sample_indices.slice(0,12).join('、')}}{{group.sample_indices.length>12?'…':''}}</small></div><div class="actions"><button class="secondary" :disabled="busy" @click="inspect(group.key)">查看样本</button><button class="secondary" :disabled="busy" @click="download(group.key)">下载明细</button></div></article></div><p class="method-note">{{data.assumption}}</p><details class="failure-detail" open v-if="detail"><summary>{{selectedLabel}} · {{detail.length}} 个样本</summary><div class="actions"><button class="secondary" :disabled="busy" @click="download(selected)">下载该组合明细 ↓</button><button class="secondary" :disabled="busy" @click="inspect('')">查看全部失败样本</button></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>强度</th><th>白度</th><th>回收率</th><th>成本</th><th>失败组合</th></tr></thead><tbody><tr v-for="s in display" :key="s.index"><td>{{s.index}}</td><td>{{fixed(s.strength)}}</td><td>{{fixed(s.whiteness)}}</td><td>{{pct(s.recycled)}}</td><td>{{fixed(s.cost)}}</td><td>{{s.combination_label}}</td></tr></tbody></table></div><small v-if="detail.length>limit">仅显示前 {{limit}} 条，下载明细可查看全部 {{detail.length}} 条。 <button class="link-button" @click="showAll=true">展开全部</button></small></details></template></section></template>
